import torch

def run(x, n):
    return torch.special.chebyshev_polynomial_w(x, n)

def _dtype_from_context(ctx, name):
    return getattr(torch, ctx[f"{name}__dtype"])

def gen_inputs(ctx, device):
    x = torch.rand(
        ctx["x__shape"], dtype=_dtype_from_context(ctx, "x"), device=device
    ) * 2.0 - 1.0
    return {"x": x}
